// Package conv converts between the beenfar API's protobuf messages and the
// provider's Terraform models.
//
// The field-by-field mapping is generated by goverter into gen/ from the
// Converter interface; this file holds the interface and the value rules it
// calls through `extend` (Terraform value types, enums, sets). Conversions
// to the models fill in every attribute; package provider then nulls the
// ones a configuration does not manage.
package conv

//go:generate rm -rf gen
//go:generate go run github.com/jmattheis/goverter/cmd/goverter@v1.11.1 gen .

import (
	"fmt"
	"math"
	"slices"
	"strings"

	"github.com/hashicorp/terraform-plugin-framework/attr"
	"github.com/hashicorp/terraform-plugin-framework/types"

	adminv1 "github.com/jacobalberty/beenfar/api/gen/go/beenfar/admin/v1"
	configv1 "github.com/jacobalberty/beenfar/api/gen/go/beenfar/config/v1"
	"github.com/jacobalberty/terraform-provider-beenfar/internal/model"
)

// Converter is implemented by gen/ (package convgen) as plain functions.
//
// Field names differ only in initialism case (Id/ID, VlanId/VlanID), hence
// matchIgnoreCase. Output-only fields (etag, timestamps) are not part of the
// models: the etag travels in the resource's private state.
//
// goverter:converter
// goverter:output:file ./gen/conv.go
// goverter:output:package github.com/jacobalberty/terraform-provider-beenfar/internal/conv/gen:convgen
// goverter:output:format function
// goverter:matchIgnoreCase
// goverter:ignoreUnexported
// goverter:useZeroValueOnPointerInconsistency
// goverter:extend String FromString Bool FromBool Int64 Uint32ToInt64 Int64ToUint32 StringSet FromStringSet
// goverter:extend WifiSecurity FromWifiSecurity WifiBand FromWifiBand Tagging FromTagging PoeMode FromPoeMode
// goverter:extend DeviceState Readoption AdapterKind
type Converter interface {
	NetworkToModel(*configv1.Network) model.Network
	// goverter:ignore Etag CreateTime UpdateTime
	NetworkFromModel(model.Network) (*configv1.Network, error)

	WifiNetworkToModel(*configv1.WifiNetwork) model.WifiNetwork
	// goverter:ignore Etag CreateTime UpdateTime RadiusProfile
	WifiNetworkFromModel(model.WifiNetwork) (*configv1.WifiNetwork, error)

	// The shared secret is never returned.
	// goverter:ignore SharedSecret
	RadiusServerToModel(*configv1.RadiusServer) model.RadiusServer
	// goverter:ignore Etag CreateTime UpdateTime SharedSecretVersion
	RadiusServerFromModel(model.RadiusServer) (*configv1.RadiusServer, error)

	SwitchPortToModel(*configv1.SwitchPort) model.SwitchPort
	// goverter:ignore Etag CreateTime UpdateTime
	SwitchPortFromModel(model.SwitchPort) (*configv1.SwitchPort, error)

	DeviceToModel(*configv1.Device) model.Device
	DevicesToModel([]*configv1.Device) []model.Device
	// goverter:ignore WaitForDevice
	AdoptedDeviceToModel(*configv1.Device) model.AdoptedDevice

	AdapterToModel(*adminv1.Adapter) model.Adapter
}

func String(s string) types.String     { return types.StringValue(s) }
func FromString(s types.String) string { return s.ValueString() }
func Bool(b bool) types.Bool           { return types.BoolValue(b) }
func FromBool(b types.Bool) bool       { return b.ValueBool() }
func Int64(v int64) types.Int64        { return types.Int64Value(v) }

func Uint32ToInt64(v uint32) types.Int64 { return types.Int64Value(int64(v)) }

func Int64ToUint32(v types.Int64) (uint32, error) {
	n := v.ValueInt64()
	if n < 0 || n > math.MaxUint32 {
		return 0, fmt.Errorf("%d is out of range", n)
	}
	return uint32(n), nil
}

// StringSet returns a set of strings; an empty list becomes an empty set.
func StringSet(s []string) types.Set {
	elems := make([]attr.Value, 0, len(s))
	for _, v := range s {
		elems = append(elems, types.StringValue(v))
	}
	return types.SetValueMust(types.StringType, elems)
}

// FromStringSet returns the set's strings, sorted; null and unknown sets are
// empty.
func FromStringSet(s types.Set) []string {
	out := []string{}
	for _, e := range s.Elements() {
		if v, ok := e.(types.String); ok && !v.IsNull() && !v.IsUnknown() {
			out = append(out, v.ValueString())
		}
	}
	slices.Sort(out)
	return out
}

// enumName turns WIFI_SECURITY_WPA_PERSONAL into wpa_personal, given the
// prefix WIFI_SECURITY_. The unspecified value becomes "".
func enumName(full, prefix string) string {
	name := strings.ToLower(strings.TrimPrefix(full, prefix))
	if name == "unspecified" {
		return ""
	}
	return name
}

// enumValue is the reverse of enumName over the values in names.
func enumValue[E ~int32](v types.String, prefix, field string, names map[string]int32) (E, error) {
	s := v.ValueString()
	if s == "" {
		return 0, nil
	}
	n, ok := names[prefix+strings.ToUpper(s)]
	if !ok || n == 0 {
		return 0, fmt.Errorf("unknown %s %q", field, s)
	}
	return E(n), nil
}

func WifiSecurity(e configv1.WifiSecurity) types.String {
	return types.StringValue(enumName(e.String(), "WIFI_SECURITY_"))
}

func FromWifiSecurity(v types.String) (configv1.WifiSecurity, error) {
	return enumValue[configv1.WifiSecurity](v, "WIFI_SECURITY_", "security", configv1.WifiSecurity_value)
}

func WifiBand(e configv1.WifiBand) types.String {
	return types.StringValue(enumName(e.String(), "WIFI_BAND_"))
}

func FromWifiBand(v types.String) (configv1.WifiBand, error) {
	return enumValue[configv1.WifiBand](v, "WIFI_BAND_", "band", configv1.WifiBand_value)
}

